+  expect(moved.y).toBeCloseTo(stayed.y);
+});
+
+/** 画面の (100, 50) から 200x100 の矩形を 45 度回して描いたもの。中心は (200, 100)。 */
+const TurnedBounds: RotatedBounds = {
+  unrotated: { left: 100, top: 50, width: 200, height: 100 },
